def transform(grid):
    out = [row[:] for row in grid]
    h, w = len(grid), len(grid[0])
    from collections import Counter
    background = Counter(v for row in grid for v in row).most_common(1)[0][0]
    for dr, dc in ((1, 1), (1, -1), (-1, 1), (-1, -1)):
        for r in range(h):
            for c in range(w):
                color = grid[r][c]
                if color == background:
                    continue
                pr, pc = r - dr, c - dc
                nr, nc = r + dr, c + dc
                # Start only at the first cell in a diagonal run; require a pair.
                if 0 <= pr < h and 0 <= pc < w and grid[pr][pc] == color:
                    continue
                if not (0 <= nr < h and 0 <= nc < w and grid[nr][nc] == color):
                    continue
                er, ec = nr, nc
                while 0 <= er + dr < h and 0 <= ec + dc < w and grid[er + dr][ec + dc] == color:
                    er, ec = er + dr, ec + dc
                rr, cc = er + dr, ec + dc
                while 0 <= rr < h and 0 <= cc < w and grid[rr][cc] == background:
                    out[rr][cc] = color
                    rr, cc = rr + dr, cc + dc
    return out
